-- PostgreSQL reference schema. The FastAPI app creates the equivalent SQLite schema for development.
CREATE TABLE users (id uuid PRIMARY KEY, email varchar(255) UNIQUE NOT NULL, full_name varchar(120) NOT NULL, branch varchar(80) NOT NULL, semester integer NOT NULL, role varchar(20) NOT NULL DEFAULT 'student', password_hash varchar(255) NOT NULL, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE notes (id uuid PRIMARY KEY, title varchar(180) NOT NULL, description text NOT NULL DEFAULT '', subject varchar(100) NOT NULL, branch varchar(80) NOT NULL, semester integer NOT NULL, academic_year varchar(20), tags varchar(500) NOT NULL DEFAULT '', original_filename varchar(255) NOT NULL, storage_path varchar(500) NOT NULL, file_type varchar(30) NOT NULL, file_size integer NOT NULL, uploader_id uuid NOT NULL REFERENCES users(id), status varchar(20) NOT NULL DEFAULT 'pending', download_count integer NOT NULL DEFAULT 0, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE bookmarks (id bigserial PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, note_id uuid NOT NULL REFERENCES notes(id) ON DELETE CASCADE, created_at timestamp NOT NULL DEFAULT now(), UNIQUE(user_id,note_id));
CREATE INDEX notes_filters ON notes (status, branch, semester, subject, created_at DESC);
